INSERT INTO content_pages (id, draft_json, published_json, draft_updated_at, published_at)
VALUES ('home', '{"hero":{"eyebrow":"מערכות AI ואוטומציה לעסקים","headlineLine1":"בסוף מישהו","headlineLine2":"צריך לזכור.","lead":"מי דיבר עם הלקוח, מה סוכם ומה עוד צריך לקרות. אנחנו בונים מערכות שעושות סדר במידע ומטפלות בפעולות שאפשר להגדיר מראש."},"seo":{"title":"LAHAV AI, מערכות ואוטומציות שעושות סדר בעסק","description":"מערכות שעושות סדר במידע העסקי ומטפלות בפעולות שאפשר להגדיר מראש: CRM, אוטומציות, אתרים, אפליקציות ותוכן בסיוע AI.","ogTitle":"LAHAV AI, מערכות ואוטומציות שעושות סדר בעסק","ogDescription":"מערכות שעושות סדר במידע העסקי ומטפלות בפעולות שאפשר להגדיר מראש: CRM, אוטומציות, אתרים, אפליקציות ותוכן בסיוע AI.","ogImage":"","noindex":false}}', '{"hero":{"eyebrow":"מערכות AI ואוטומציה לעסקים","headlineLine1":"בסוף מישהו","headlineLine2":"צריך לזכור.","lead":"מי דיבר עם הלקוח, מה סוכם ומה עוד צריך לקרות. אנחנו בונים מערכות שעושות סדר במידע ומטפלות בפעולות שאפשר להגדיר מראש."},"seo":{"title":"LAHAV AI, מערכות ואוטומציות שעושות סדר בעסק","description":"מערכות שעושות סדר במידע העסקי ומטפלות בפעולות שאפשר להגדיר מראש: CRM, אוטומציות, אתרים, אפליקציות ותוכן בסיוע AI.","ogTitle":"LAHAV AI, מערכות ואוטומציות שעושות סדר בעסק","ogDescription":"מערכות שעושות סדר במידע העסקי ומטפלות בפעולות שאפשר להגדיר מראש: CRM, אוטומציות, אתרים, אפליקציות ותוכן בסיוע AI.","ogImage":"","noindex":false}}', '2026-09-01T13:12:59.030Z', '2026-09-01T13:12:59.030Z')
