INSERT INTO services_content (slug, draft_json, published_json, draft_updated_at, published_at)
VALUES ('crm', '{"name":"מערכות CRM חכמות","short":"CRM","lead":"כל לקוח במקום אחד. תמיד ברור מה קרה ומה הצעד הבא.","pain":"היום חלק מהמידע בוואטסאפ, חלק במייל, חלק באקסל, וחלק פשוט בראש של מישהו. נסדר מקום אחד שמרכז את מה שחשוב, כדי שלא תצטרכו לחפש בשיחות ישנות כדי להיזכר מה סוכם.","points":["כל פנייה מגיעה למקום אחד","רואים בשנייה מה קרה ומה הלאה","אפשר להגדיר תזכורות ומעקב"],"h1a":"תפסיקו לחפש בוואטסאפ","h1b":"כדי להיזכר מה סוכם.","pageLead":"כל מה שצריך לדעת על לקוח נמצא בכרטיס אחד: מה סוכם, מי מטפל ומה השלב הבא.","symptomsTitle":"ככה זה נראה ביום יום","symptoms":["לפני כל שיחה צריך לחפש מה נאמר בפעם הקודמת","לא ברור מי מטפל בפנייה ואיפה היא עומדת","לקוח מחכה לחזרה, ופשוט לא חוזרים אליו","על \"מה מצב המכירות\" אין תשובה בלי לאסוף הכל ביד"],"buildTitle":"מה נסדר לכם","build":[{"t":"הפניות נכנסות לבד","d":"אפשר להגדיר שפניות מהמקורות שתבחרו ייקלטו ישר למערכת, בלי שאף אחד יעתיק שורה."},{"t":"הכל על כרטיס אחד","d":"מה סוכם, מה נשלח, מה עוד פתוח, ומה השלב הבא. פותחים ורואים."},{"t":"תזכורות ומעקב","d":"אפשר להגדיר תזכורות ומעקב בהתאם לתהליך, כך שהמערכת תציף מי מחכה לחזרה."},{"t":"תמונת מצב בלי לאסוף ידנית","d":"לראות איפה הדברים עומדים בלי לבנות דוח מאפס בכל פעם שמישהו שואל."}],"closing":"בואו נראה איך זה נראה אצלכם","closingBody":"נעבור יחד על מסלול הלקוח אצלכם, מהפנייה הראשונה ועד הסגירה, ונסמן איפה המידע נופל.","note":"התרשים הוא המחשה בלבד. המבנה אצלכם ייקבע לפי איך שאתם עובדים, ובהתאם לתהליך ולחיבורים שנבחר יחד.","seo":{"title":"מערכות CRM חכמות | LAHAV AI","description":"בונים מערכת CRM שמרכזת לקוחות, פניות ומשימות במקום אחד, ונותנת תמונה ברורה של כל לקוח ומה השלב הבא.","ogTitle":"מערכות CRM חכמות | LAHAV AI","ogDescription":"בונים מערכת CRM שמרכזת לקוחות, פניות ומשימות במקום אחד, ונותנת תמונה ברורה של כל לקוח ומה השלב הבא.","ogImage":"","noindex":false}}', '{"name":"מערכות CRM חכמות","short":"CRM","lead":"כל לקוח במקום אחד. תמיד ברור מה קרה ומה הצעד הבא.","pain":"היום חלק מהמידע בוואטסאפ, חלק במייל, חלק באקסל, וחלק פשוט בראש של מישהו. נסדר מקום אחד שמרכז את מה