VALUES ('automations', '{"name":"אוטומציות עסקיות","short":"אוטומציות","lead":"העבודה החוזרת רצה ברקע. אתם נשארים עם ההחלטות.","pain":"להעתיק פרטים ממקום למקום, לשלוח הודעת מעקב, להזכיר לעצמכם לחזור ללקוח, לעדכן טבלה. את כל אלה אפשר להגדיר פעם אחת ולתת למערכת לעשות. מה שדורש שיקול דעת ממשיך להגיע אליכם.","points":["מה שחוזר כל שבוע רץ לבד","הכללים נקבעים על ידכם מראש","מה שדורש החלטה מגיע אליכם"],"h1a":"לא כל פעולה שחוזרת על עצמה","h1b":"צריכה לעבור דרככם.","pageLead":"אוטומציה טובה לא מחליטה במקומכם. היא עושה בדיוק מה שהגדרתם מראש, ואת מה שדורש שיקול דעת היא מעבירה אליכם.","symptomsTitle":"איפה זה עוזר בדרך כלל","symptoms":["להעתיק פרטים ממערכת אחת לשנייה","לשלוח הודעת מעקב אחרי שמישהו פנה","תזכורות שתלויות בזה שמישהו יזכור","לעדכן טבלאות ורשימות ביד"],"buildTitle":"איך אוטומציה עובדת","build":[{"t":"קורה משהו","d":"נכנסת פנייה, מתקבל תשלום, מגיע תאריך, משתנה סטטוס."},{"t":"המערכת בודקת את הכללים שהגדרנו","d":"אין כאן ניחוש. בדיוק מה שהוגדר מראש, ורק במקרים שהוגדרו מראש."},{"t":"הפעולה קורית","d":"ההודעה נשלחת, הרשומה מתעדכנת, המשימה נפתחת. בלי שנגעתם."},{"t":"ואם צריך אתכם","d":"התהליך עוצר ומגיע אליכם, במקום להמשיך לרוץ לבד ולעשות נזק."}],"closing":"מה חוזר על עצמו אצלכם כל שבוע?","closingBody":"ספרו לנו מה חוזר על עצמו אצלכם כל שבוע. נגיד בכנות מה שווה להפוך לאוטומטי ומה עדיף להשאיר ידני.","note":"הדוגמאות כאן ממחישות את העיקרון. מה בדיוק ירוץ אוטומטית אצלכם ייקבע באפיון.","seo":{"title":"אוטומציות עסקיות | LAHAV AI","description":"מעבירים את הפעולות שחוזרות על עצמן למערכת שעושה אותן לבד, ומשאירים לכם את ההחלטות.","ogTitle":"אוטומציות עסקיות | LAHAV AI","ogDescription":"מעבירים את הפעולות שחוזרות על עצמן למערכת שעושה אותן לבד, ומשאירים לכם את ההחלטות.","ogImage":"","noindex":false}}', '{"name":"אוטומציות עסקיות","short":"אוטומציות","lead":"העבודה החוזרת רצה ברקע. אתם נשארים עם ההחלטות.","pain":"להעתיק פרטים ממקום למקום, לשלוח הודעת מעקב, להזכיר לעצמכם לחזור ללקוח, לעדכן טבלה. את כל אלה אפשר להגדיר פעם אחת ולתת למערכת לעשות. מה שדורש שיקול דעת ממשיך להגיע אליכם.","points":["מה שחוזר כל שבוע רץ לבד","הכללים נקבעים על ידכם מראש","מה שדורש החלטה מגיע אליכם"],"h1a":"לא כל פעולה שחוזרת על עצמה","h1b":"צריכה לעבור דרככם.","pageLead":"אוטומציה טובה לא מחליטה במקומכם. היא עושה בדיוק מה שהגדרתם מראש, ואת מה שדורש שיקול דעת היא מעבירה אליכם.","symptomsTitle":"איפה זה עוזר בדרך כלל","symptoms":["להעתיק פרטים ממערכת אחת לשנייה","לשלוח הודעת מעקב אחרי שמישהו פנה","תזכורות שתלויות בזה שמישהו יזכור","לעדכן טבלאות ורשימות ביד"],"buildTitle":"איך אוטומציה עובדת","build":[{"t":"קורה משהו","d":"נכנסת פנייה, מתקבל תשלום, מגיע תאריך, משתנה סטטוס."},{"t":"המערכת בודקת את הכללים שהגדרנו","d":"אין כאן ניחוש. בדיוק מה שהוגדר מראש, ורק במקרים שהוגדרו מראש."},{"t":"הפעולה קורית","d":"ההודעה נשלחת, הרשומה מתעדכנת, המשימה נפתחת. בלי שנגעתם."},{"t":"ואם צריך אתכם","d":"התהליך עוצר ומגיע אליכם, במקום להמשיך לרוץ לבד ולעשות נזק."}],"closing":"מה חוזר על עצמו אצלכם כל שבוע?","closingBody":"ספרו לנו מה חוזר על עצמו אצלכם כל שבוע. נגיד בכנות מה שווה להפוך לאוטומטי ומה עדיף להשאיר ידני.","note":"הדוגמאות כאן ממחישות את העיקרון. מה בדיוק ירוץ אוטומטית אצלכם ייקבע באפיון.","seo":{"title":"אוטומציות עסקיות | LAHAV AI","description":"מעבירים את הפעולות שחוזרות על עצמן למערכת שעושה אותן לבד, ומשאירים לכם את ההחלטות.","ogTitle":"אוטומציות עסקיות | LAHAV AI","ogDescription":"מעבירים את הפעולות שחוזרות על עצמן למערכת שעושה אותן לבד, ומשאירים לכם את ההחלטות.","ogImage":"","noindex":false}}', '2026-09-01T13:12:59.030Z', '2026-09-01T13:12:59.030Z')
