INSERT INTO services_content (slug, draft_json, published_json, draft_updated_at, published_at)
VALUES ('web-development', '{"name":"פיתוח אתרים","short":"אתרים","lead":"אתר יפה זה רק ההתחלה. אתר טוב מוביל את המבקר לצעד הבא.","pain":"לפני שמדברים על צבעים, נשאל מי נכנס אליכם ומה אתם רוצים שיעשה. מהתשובה נגזרים המבנה, הטקסטים והמקומות שבהם משאירים פרטים.","points":["כל עמוד מוביל לצעד הבא","טקסטים בשפה של בעל עסק","עובד באותה בהירות גם בנייד"],"h1a":"אתר יפה זה רק ההתחלה.","h1b":"אתר טוב מוביל לצעד הבא.","pageLead":"מישהו נכנס לאתר ומנסה להבין מהר אם הוא במקום הנכון. המבנה, המסר והצעד הבא צריכים לעזור לו להבין מה לעשות מכאן.","symptomsTitle":"מה נשאל לפני שנעצב","symptoms":["מי נכנס אליכם ומה הוא מחפש","מה הפעולה שאתם רוצים שיעשה","מה הוא צריך להבין לפני שיהיה מוכן לזה","מה קורה אצלכם ברגע שהוא משאיר פרטים"],"buildTitle":"מה נעשה בפועל","build":[{"t":"מבנה ומסלול","d":"נסדר את העמודים ואת התוכן כך שבכל רגע ברור מה הצעד הבא."},{"t":"טקסטים שמסבירים","d":"בשפה של בעל עסק, בלי מונחים שצריך לתרגם כדי להבין."},{"t":"נקודות פעולה","d":"המקומות שבהם אפשר להשאיר פרטים או לעשות את הפעולה שרצינו להוביל אליה."},{"t":"נייד באותה רמה","d":"אותו מסלול ואותה בהירות גם במסך קטן, לא גרסה מקוצצת."}],"closing":"רוצים אתר שמוביל לפעולה?","closingBody":"נתחיל מהשאלה מי נכנס אליכם ומה אתם רוצים שיקרה. המבנה והעיצוב נגזרים מזה.","note":"התרשים ממחיש מסלול טיפוסי. המבנה שלכם ייקבע לפי הקהל והמטרה של האתר.","seo":{"title":"פיתוח אתרים | LAHAV AI","description":"אתרים עסקיים שנבנים סביב מטרה ומסלול ברור: מי נכנס, מה הוא מחפש, ולאן הוא אמור להגיע.","ogTitle":"פיתוח אתרים | LAHAV AI","ogDescription":"אתרים עסקיים שנבנים סביב מטרה ומסלול ברור: מי נכנס, מה הוא מחפש, ולאן הוא אמור להגיע.","ogImage":"","noindex":false}}', '{"name":"פיתוח אתרים","short":"אתרים","lead":"אתר יפה זה רק ההתחלה. אתר טוב מוביל את המבקר לצעד הבא.","pain":"לפני שמדברים על צבעים, נשאל מי נכנס אליכם ומה אתם רוצים שיעשה. מהתשובה נגזרים המבנה, הטקסטים והמקומות שבהם משאירים פרטים.","points":["כל עמוד מוביל לצעד הבא","טקסטים בשפה של בעל עסק","עובד באותה בהירות גם בנייד"],"h1a":"אתר יפה זה רק ההתחלה.","h1b":"אתר טוב מוביל לצ