INSERT INTO services_content (slug, draft_json, published_json, draft_updated_at, published_at)
VALUES ('app-development', '{"name":"פיתוח אפליקציות","short":"אפליקציות","lead":"כשאין מערכת שמתאימה לתהליך, אפשר לבנות אחת סביבו.","pain":"לפעמים משלמים על שלוש מערכות ועדיין עובדים באקסל, כי אף אחת מהן לא בנויה לאיך שאתם עובדים. במקרה כזה עדיף לבנות סביב התהליך שלכם במקום לכופף את העסק לכלי.","points":["נבנה סביב איך שאתם עובדים","רק המסכים שבאמת צריך","עוברים בדיקה לפני שממשיכים"],"h1a":"לא מצאתם מערכת שמתאימה לתהליך?","h1b":"אפשר לבנות אחת סביבו.","pageLead":"יש עסקים שעובדים בצורה מסוימת כי ככה נכון להם. אם שום כלי קיים לא תומך בזה, אפשר לבנות סביב התהליך במקום להתכופף לכלי.","symptomsTitle":"מתי זה באמת מוצדק","symptoms":["התהליך שלכם ייחודי ואף כלי לא באמת תומך בו","משלמים על כמה מערכות ועדיין עובדים באקסל","הצוות המציא עקיפות ידניות כדי שהמערכת תסתדר","יש משהו שקורה כל יום ואין לו מקום מסודר"],"buildTitle":"איך נתחיל","build":[{"t":"נתחיל מהצורך","d":"מה בדיוק צריך לקרות בעסק, ומי אמור לעשות את זה."},{"t":"נמפה את המסכים","d":"מה רואים בכל מסך, מה מזינים בו, ומה קורה אחרי."},{"t":"נגדיר את הפעולות","d":"רק הכפתורים שבאמת צריך. מסך עמוס הוא מסך שלא משתמשים בו."},{"t":"נבדוק לפני שנמשיך","d":"נעבור על הזרימה, המסכים והפעולות לפני שמתקדמים לשלב הבא."}],"closing":"יש לכם תהליך שאף כלי לא מכסה?","closingBody":"תארו לנו איך אתם עובדים היום. לפעמים התשובה היא לבנות, ולפעמים פשוט להגדיר נכון משהו קיים.","note":"המסכים בתרשים הם המחשה בלבד, לא צילום של מוצר קיים. הטכנולוגיה ואופן ההפצה ייקבעו באפיון.","seo":{"title":"פיתוח אפליקציות | LAHAV AI","description":"תוכנה מותאמת לתהליך העסקי הספציפי שלכם, כשכלים קיימים פשוט לא מתאימים.","ogTitle":"פיתוח אפליקציות | LAHAV AI","ogDescription":"תוכנה מותאמת לתהליך העסקי הספציפי שלכם, כשכלים קיימים פשוט לא מתאימים.","ogImage":"","noindex":false}}', '{"name":"פיתוח אפליקציות","short":"אפליקציות","lead":"כשאין מערכת שמתאימה לתהליך, אפשר לבנות אחת סביבו.","pain":"לפעמים משלמים על שלוש מערכות ועדיין עובדים באקסל, כי אף אחת מהן לא בנויה לאיך שאתם עובדים. במקרה כזה עדיף לבנות סביב התהליך שלכם במקום לכופף את העסק לכלי.","points":["נבנה סביב איך שאתם עובדים","רק המסכים שבאמת צריך","עוברים בדיקה לפני שממשיכים"],"h1a":"לא מצאתם מערכת שמתאימה לתהליך?","h1b":"אפשר לבנות אחת סביבו.","pageLead":"יש עסקים שעובדים בצורה מסוימת כי ככה נכון להם. אם שום כלי קיים לא תומך בזה, אפשר לבנות סביב התהליך במקום להתכופף לכלי.","symptomsTitle":"מתי זה באמת מוצדק","symptoms":["התהליך שלכם ייחודי ואף כלי לא באמת תומך בו","משלמים על כמה מערכות ועדיין עובדים באקסל","הצוות המציא עקיפות ידניות כדי שהמערכת תסתדר","יש משהו שקורה כל יום ואין לו מקום מסודר"],"buildTitle":"איך נתחיל","build":[{"t":"נתחיל מהצורך","d":"מה בדיוק צריך לקרות בעסק, ומי אמור לעשות את זה."},{"t":"נמפה את המסכים","d":"מה רואים בכל מסך, מה מזינים בו, ומה קורה אחרי."},{"t":"נגדיר את הפעולות","d":"רק הכפתורים שבאמת צריך. מסך עמוס הוא מסך שלא משתמשים בו."},{"t":"נבדוק לפני שנמשיך","d":"נעבור על הזרימה, המסכים והפעולות לפני שמתקדמים לשלב הבא."}],"closing":"יש לכם תהליך שאף כלי לא מכסה?","closingBody":"תארו לנו איך אתם עובדים היום. לפעמים התשובה היא לבנות, ולפעמים פשוט להגדיר נכון משהו קיים.","note":"המסכים בתרשים הם המחשה בלבד, לא צילום של מוצר קיים. הטכנולוגיה ואופן ההפצה ייקבעו באפיון.","seo":{"title":"פיתוח אפליקציות | LAHAV AI","description":"תוכנה מותאמת לתהליך העסקי הספציפי שלכם, כשכלים קיימים פשוט לא מתאימים.","ogTitle":"פיתוח אפליקציות | LAHAV AI","ogDescription":"תוכנה מותאמת לתהליך העסקי הספציפי שלכם, כשכלים קיימים פשוט לא מתאימים.","ogImage":"","noindex":false}}', '2026-09-01T13:12:59.030Z', '2026-09-01T13:12:59.030Z')
