INSERT INTO services_content (slug, draft_json, published_json, draft_updated_at, published_at)
VALUES ('ai-content', '{"name":"יצירת תוכן באמצעות AI","short":"תוכן","lead":"AI יכול לעזור לייצר טיוטה. מה שמתפרסם בשם העסק עדיין עובר דרככם.","pain":"AI יכול להביא אתכם מדף ריק לטיוטה שאפשר לעבוד איתה. מה שהוא לא עושה זה להחליט מה נכון להגיד בשם העסק שלכם. הקריאה, התיקון והאישור נשארים אצלכם.","points":["מתחילים ממה שרוצים להשיג","טיוטה ראשונה מהר","שום דבר לא יוצא בלי אישור"],"h1a":"AI יכול לעזור לייצר טיוטה.","h1b":"מה שמתפרסם עובר דרככם.","pageLead":"מה שעוצר בדרך כלל זה לא חוסר ברעיונות, זה הדף הריק. מה ש-AI לא אמור לעשות זה להחליט מה יוצא החוצה בשם העסק שלכם.","symptomsTitle":"ככה זה נראה ביום יום","symptoms":["יודעים שצריך לכתוב, ואף פעם אין לזה זמן","וכשכבר כותבים, זה יוצא כללי מדי","אין סדר עבודה, אז זה קורה בהתקפים","קשה לשמור על אותו קול לאורך זמן"],"buildTitle":"איך נעבוד","build":[{"t":"נתחיל ממטרה","d":"למי כותבים, ומה אתם רוצים שיקרה אחרי שיסיימו לקרוא."},{"t":"בריף קצר","d":"נושא, זווית, ומה חייב להופיע. חמש שורות, לא מסמך."},{"t":"טיוטה בסיוע AI","d":"יש טקסט על הדף. לא מוכן, אבל אפשר לעבוד איתו."},{"t":"בקרה ואישור","d":"אתם קוראים, מתקנים, מאשרים. רק אז זה יוצא החוצה."}],"closing":"רוצים סדר בתוכן?","closingBody":"נבנה יחד סדר עבודה לתוכן: ממה מתחילים, מי כותב, ומי מאשר לפני שזה יוצא.","note":"התרשים מציג את סדר העבודה. היקף השירות המדויק ייקבע יחד איתכם.","seo":{"title":"יצירת תוכן באמצעות AI | LAHAV AI","description":"תהליך תוכן מסודר: מטרה עסקית, בריף, טיוטה בעזרת AI, בדיקה ואישור שלכם, ורק אז שימוש.","ogTitle":"יצירת תוכן באמצעות AI | LAHAV AI","ogDescription":"תהליך תוכן מסודר: מטרה עסקית, בריף, טיוטה בעזרת AI, בדיקה ואישור שלכם, ורק אז שימוש.","ogImage":"","noindex":false}}', '{"name":"יצירת תוכן באמצעות AI","short":"תוכן","lead":"AI יכול לעזור לייצר טיוטה. מה שמתפרסם בשם העסק עדיין עובר דרככם.","pain":"AI יכול להביא אתכם מדף ריק לטיוטה שאפשר לעבוד איתה. מה שהוא לא עושה זה להחליט מה נכון להגיד בשם העסק שלכם. הקריאה, התיקון והאישור נשארים אצלכם.","points":["מתחילים ממה שרוצים להשיג","טיוטה ראשונה מהר","שום דבר לא יוצא בלי אישור"],"h1a":"AI י