INSERT INTO faq_items (id, question, answer, sort_order, enabled, created_at, updated_at)
VALUES ('seed-faq-1', 'אני לא טכני בכלל. זה בכלל בשבילי?', 'כן, וזו בדיוק נקודת המוצא. השיחה מתחילה מאיך העסק עובד היום, לא מטכנולוגיה. אנחנו מתרגמים את זה למערכת, ואתם לא צריכים להבין מה רץ מתחת למכסה המנוע כדי להשתמש בה.', 0, 1, '2026-09-01T13:12:59.030Z', '2026-09-01T13:12:59.030Z')
ON CONFLICT(id) DO NOTHING;

INSERT INTO faq_items (id, question, answer, sort_order, enabled, created_at, updated_at)
VALUES ('seed-faq-2', 'כמה זה עולה?', 'אין מחירון קבוע, כי אין שני עסקים זהים. המחיר נגזר מהיקף העבודה בפועל, והוא נקבע רק אחרי שיחת ההיכרות והאפיון. אתם מקבלים הצעה ברורה לפני שמתחילים, בלי הפתעות.', 1, 1, '2026-09-01T13:12:59.030Z', '2026-09-01T13:12:59.030Z')
ON CONFLICT(id) DO NOTHING;

INSERT INTO faq_items (id, question, answer, sort_order, enabled, created_at, updated_at)
VALUES ('seed-faq-3', 'כמה זמן זה לוקח?', 'זה תלוי במה שבונים. אחרי האפיון תדעו מה נבנה, באיזה סדר, ומה מוכן ראשון. אנחנו מעדיפים להעלות משהו שעובד מוקדם ולהרחיב ממנו, במקום להיעלם לחודשים ולחזור עם הכל בבת אחת.', 2, 1, '2026-09-01T13:12:59.030Z', '2026-09-01T13:12:59.030Z')
ON CONFLICT(id) DO NOTHING;

INSERT INTO faq_items (id, question, answer, sort_order, enabled, created_at, updated_at)
VALUES ('seed-faq-4', 'אני כבר משלם על כמה כלים. צריך להחליף אותם?', 'לרוב לא. במקרים רבים הבעיה היא לא שחסר כלי, אלא שהכלים לא מדברים ביניהם. קודם נבדוק מה כבר עובד אצלכם ומה שווה לחבר, ורק אם באמת אין התאמה נדבר על להחליף.', 3, 1, '2026-09-01T13:12:59.030Z', '2026-09-01T13:12:59.030Z')
ON CONFLICT(id) DO NOTHING;

INSERT INTO faq_items (id, question, answer, sort_order, enabled, created_at, updated_at)
VALUES ('seed-faq-5', 'מה קורה למידע שלנו?', 'אנחנו עובדים לפי הרשאות, ניגשים רק למה שנדרש לעבודה, ומסבירים מראש איפה כל דבר נשמר. אם יש דרישות פרטיות מיוחדות בתחום שלכם, מדברים עליהן באפיון ולא בדיעבד.', 4, 1, '2026-09-01T13:12:59.030Z', '2026-09-01T13:12:59.030Z')
ON CONFLICT(id) DO NOTHING;

INSERT INTO faq_items (id, question, answer, sort_order, enabled, created_at, updated_at)
VALUES ('seed-faq-6', 'ה-AI יחליט במקומנו?', 'לא. אנחנו בונים מערכות שבהן ההחלטות נשארות אצלכם. מה שחוזר על עצמו ולא דורש שיקול דעת רץ אוטומטית, וכל מה שדורש החלטה מגיע אליכם לאישור.', 5, 1, '2026-09-01T13:12:59.030Z', '2026-09-01T13:12:59.030Z')
ON CONFLICT(id) DO NOTHING;

INSERT INTO faq_items (id, question, answer, sort_order, enabled, created_at, updated_at)
VALUES ('seed-faq-7', 'ומה אם משהו נשבר?', 'מערכת אמיתית צריכה גם תחזוקה. מסכמים מראש איך פונים ומה נחשב תקלה דחופה, כדי שיהיה ברור למי ואיך לפנות.', 6, 1, '2026-09-01T13:12:59.030Z', '2026-09-01T13:12:59.030Z')
ON CONFLICT(id) DO NOTHING;

INSERT INTO faq_items (id, question, answer, sort_order, enabled, created_at, updated_at)
VALUES ('seed-faq-8', 'איך מתחילים?', 'בשיחת היכרות של 30 דקות, בלי התחייבות. נעבור על איך שאתם עובדים היום, ונגיד בכנות איפה יש מה לשפר ואיפה פשוט לא צריך. אם זה לא מתאים, נגיד את זה.', 7, 1, '2026-09-01T13:12:59.030Z', '2026-09-01T13:12:59.030Z')
ON CONFLICT(id) DO NOTHING;

